$p->exec("CREATE DATABASE IF NOT EXISTS `{$C['db']}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$p->exec("USE `{$C['db']}`");
$T="ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";$ts="created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP";
foreach([
"users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150) UNIQUE,password VARCHAR(255),role ENUM('admin','manager','serveur','cuisinier','guichet'),phone VARCHAR(30),is_active TINYINT DEFAULT 1,last_login DATETIME NULL,$ts)",
"categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),description TEXT,sort_order INT DEFAULT 0,is_active TINYINT DEFAULT 1,$ts)",
"products(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT,name VARCHAR(150),description VARCHAR(500),price DECIMAL(10,2),cost_price DECIMAL(10,2) DEFAULT 0,image VARCHAR(255),is_available TINYINT DEFAULT 1,is_featured TINYINT DEFAULT 0,preparation_time INT DEFAULT 15,sort_order INT DEFAULT 0,$ts,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT)",
"ingredients(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),unit VARCHAR(20),current_stock DECIMAL(10,3) DEFAULT 0,min_stock DECIMAL(10,3) DEFAULT 0,cost_per_unit DECIMAL(10,2) DEFAULT 0,supplier VARCHAR(100),$ts)",
"product_ingredients(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT,ingredient_id INT,quantity DECIMAL(10,3),UNIQUE(product_id,ingredient_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(ingredient_id) REFERENCES ingredients(id) ON DELETE CASCADE)",
"tables_restaurant(id INT AUTO_INCREMENT PRIMARY KEY,number INT UNIQUE,name VARCHAR(50),capacity INT,status ENUM('free','reserved','occupied','maintenance') DEFAULT 'free',zone VARCHAR(30),is_active TINYINT DEFAULT 1)",
"reservations(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(10) UNIQUE,customer_name VARCHAR(100),customer_phone VARCHAR(30),customer_email VARCHAR(150),date DATE,time TIME,duration INT DEFAULT 120,guests INT,table_id INT NULL,status ENUM('pending','confirmed','seated','completed','cancelled','no_show') DEFAULT 'pending',notes TEXT,$ts)",
"orders(id INT AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(30) UNIQUE,table_id INT NULL,user_id INT,type ENUM('dine_in','takeaway'),status ENUM('pending','confirmed','preparing','ready','served','paid','cancelled') DEFAULT 'pending',subtotal DECIMAL(10,2),discount DECIMAL(10,2) DEFAULT 0,tax DECIMAL(10,2),total DECIMAL(10,2),notes TEXT,$ts,paid_at DATETIME NULL)",
"order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT,product_id INT,quantity INT,unit_price DECIMAL(10,2),total_price DECIMAL(10,2),status VARCHAR(20) DEFAULT 'pending',notes VARCHAR(255),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id))",
"cash_registers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,opening_amount DECIMAL(10,2),closing_amount DECIMAL(10,2) NULL,total_cash_in DECIMAL(10,2) DEFAULT 0,total_cash_out DECIMAL(10,2) DEFAULT 0,expected_amount DECIMAL(10,2) NULL,status ENUM('open','closed') DEFAULT 'open',opened_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,notes TEXT)",
"payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT,amount DECIMAL(10,2),method ENUM('cash','mobile_money','card'),status ENUM('pending','completed','failed','refunded') DEFAULT 'completed',reference VARCHAR(100),phone_number VARCHAR(30),cash_register_id INT NULL,received_by INT,notes TEXT,$ts)",
"cash_movements(id INT AUTO_INCREMENT PRIMARY KEY,cash_register_id INT,type ENUM('in','out'),amount DECIMAL(10,2),reason VARCHAR(255),reference VARCHAR(100),created_by INT,$ts)",
"inventory_movements(id INT AUTO_INCREMENT PRIMARY KEY,ingredient_id INT,type ENUM('in','out','adjust'),quantity DECIMAL(10,3),reason VARCHAR(255),reference VARCHAR(100),created_by INT,$ts)"
] as $s)$p->exec("CREATE TABLE IF NOT EXISTS $s $T");
